#!/usr/bin/env node

import { pathToFileURL } from 'node:url'
import {
  normalizeBaseUrl,
  normalizeTimeoutMs,
} from './alias-commit-guard.mjs'

const PROVIDER_ID_PATTERN = /^[a-z0-9][a-z0-9_-]{0,63}$/
class AuthorizationCheckError extends Error {}

// Inspect the request generated by NextAuth without following it or exposing
// client IDs, state, PKCE material, or cookies in diagnostics.
export const verifyGoogleAuthorizationUrl = (value, baseUrl) => {
  let url
  try {
    url = new URL(value)
  } catch {
    throw new AuthorizationCheckError('Google sign-in did not return an authorization URL.')
  }
  if (url.origin !== 'https://accounts.google.com' || url.username || url.password) {
    throw new AuthorizationCheckError('Google sign-in returned an unexpected authorization origin.')
  }
  const expected = `${normalizeBaseUrl(baseUrl)}/api/auth/callback/google`
  const params = url.searchParams
  if (params.getAll('redirect_uri').length !== 1 || params.get('redirect_uri') !== expected) {
    throw new AuthorizationCheckError(`Google authorization redirect_uri mismatch: expected ${expected}.`)
  }
  if (params.get('response_type') !== 'code' || !params.get('client_id') || !params.get('state')) {
    throw new AuthorizationCheckError('Google authorization request is missing required OAuth parameters.')
  }
  if (params.get('code_challenge_method') !== 'S256' || !params.get('code_challenge')) {
    throw new AuthorizationCheckError('Google authorization request is missing S256 PKCE protection.')
  }
  return { authorizationOrigin: url.origin, callbackUrl: expected }
}

export const fetchAndVerifyGoogleAuthorization = async ({
  baseUrl,
  timeoutMs = 12000,
  fetchImpl = globalThis.fetch,
}) => {
  const base = normalizeBaseUrl(baseUrl)
  const timeout = normalizeTimeoutMs(timeoutMs)
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), timeout)
  try {
    const options = { redirect: 'error', signal: controller.signal }
    const csrfResponse = await fetchImpl(`${base}/api/auth/csrf`, options)
    if (!csrfResponse.ok) throw new AuthorizationCheckError(`Auth CSRF request failed with HTTP ${csrfResponse.status}.`)
    const { csrfToken } = await csrfResponse.json()
    if (typeof csrfToken !== 'string' || !csrfToken || csrfToken.length > 1024) {
      throw new AuthorizationCheckError('Auth CSRF endpoint did not return a valid token.')
    }
    // Node fetch has no cookie jar. Only forward NextAuth cookies to the same
    // explicitly selected origin, never to Google or a followed redirect.
    const cookies = (csrfResponse.headers.getSetCookie?.() ?? [])
      .map((cookie) => cookie.split(';', 1)[0])
      .filter((cookie) => /^(?:__Host-|__Secure-)?next-auth\.[a-z-]+=/.test(cookie))
      .join('; ')
    if (!cookies) throw new AuthorizationCheckError('Auth CSRF endpoint did not set its session cookies.')
    const response = await fetchImpl(`${base}/api/auth/signin/google`, {
      ...options,
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded', cookie: cookies },
      body: new URLSearchParams({ csrfToken, callbackUrl: base, json: 'true' }).toString(),
    })
    if (!response.ok) throw new AuthorizationCheckError(`Google sign-in request failed with HTTP ${response.status}.`)
    const payload = await response.json()
    return verifyGoogleAuthorizationUrl(payload?.url, base)
  } catch (error) {
    if (controller.signal.aborted) {
      throw new Error(`Google authorization check timed out after ${timeout} milliseconds.`)
    }
    // Fetch/JSON errors may include request data. Only emit our own bounded
    // diagnostics, not arbitrary remote response bodies or transport errors.
    if (error instanceof AuthorizationCheckError) throw error
    throw new Error('Google authorization check failed before a valid response was received.')
  } finally {
    clearTimeout(timer)
  }
}

export const normalizeProviderId = (value) => {
  const providerId = String(value || '').trim()
  if (!PROVIDER_ID_PATTERN.test(providerId)) {
    throw new Error(
      'OAuth provider ID must contain only lowercase letters, numbers, underscores, or hyphens.'
    )
  }
  return providerId
}

export const verifyAuthProviderPayload = (
  payload,
  { baseUrl, providerId }
) => {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl)
  const normalizedProviderId = normalizeProviderId(providerId)

  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new Error('Auth providers endpoint did not return a provider object.')
  }

  const provider = payload[normalizedProviderId]
  if (!provider || typeof provider !== 'object' || Array.isArray(provider)) {
    throw new Error(
      `Required OAuth provider is not configured: ${normalizedProviderId}.`
    )
  }

  if (provider.id !== normalizedProviderId || provider.type !== 'oauth') {
    throw new Error(
      `Provider ${normalizedProviderId} is not exposed as the expected OAuth provider.`
    )
  }

  if (typeof provider.name !== 'string' || !provider.name.trim()) {
    throw new Error(`Provider ${normalizedProviderId} is missing a display name.`)
  }

  const expectedSignInUrl =
    `${normalizedBaseUrl}/api/auth/signin/${normalizedProviderId}`
  const expectedCallbackUrl =
    `${normalizedBaseUrl}/api/auth/callback/${normalizedProviderId}`

  if (provider.signinUrl !== expectedSignInUrl) {
    throw new Error(
      `Provider ${normalizedProviderId} sign-in URL mismatch: expected ${expectedSignInUrl}, observed ${String(provider.signinUrl || 'missing')}.`
    )
  }

  if (provider.callbackUrl !== expectedCallbackUrl) {
    throw new Error(
      `Provider ${normalizedProviderId} callback URL mismatch: expected ${expectedCallbackUrl}, observed ${String(provider.callbackUrl || 'missing')}.`
    )
  }

  return {
    callbackUrl: expectedCallbackUrl,
    name: provider.name.trim(),
    providerId: normalizedProviderId,
    signinUrl: expectedSignInUrl,
  }
}

export const fetchAndVerifyAuthProvider = async ({
  baseUrl,
  providerId,
  timeoutMs = 12000,
  fetchImpl = globalThis.fetch,
}) => {
  if (typeof fetchImpl !== 'function') {
    throw new Error('This Node.js runtime does not provide fetch.')
  }

  const normalizedBaseUrl = normalizeBaseUrl(baseUrl)
  const normalizedProviderId = normalizeProviderId(providerId)
  const normalizedTimeout = normalizeTimeoutMs(timeoutMs)
  const url = `${normalizedBaseUrl}/api/auth/providers`
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), normalizedTimeout)

  try {
    const response = await fetchImpl(url, {
      headers: { accept: 'application/json' },
      redirect: 'error',
      signal: controller.signal,
    })
    if (!response.ok) {
      throw new Error(`Auth providers request failed with HTTP ${response.status}.`)
    }

    let payload
    try {
      payload = await response.json()
    } catch {
      throw new Error('Auth providers endpoint did not return valid JSON.')
    }

    return {
      ...verifyAuthProviderPayload(payload, {
        baseUrl: normalizedBaseUrl,
        providerId: normalizedProviderId,
      }),
      url,
    }
  } catch (error) {
    if (controller.signal.aborted) {
      throw new Error(
        `Auth providers request timed out after ${normalizedTimeout} milliseconds.`
      )
    }
    throw error
  } finally {
    clearTimeout(timer)
  }
}

const printHelp = () => {
  console.log(`Usage:
  node scripts/auth-provider-guard.mjs --base-url URL --provider PROVIDER [options]

Required:
  --base-url URL       Canonical deployment base URL
  --provider PROVIDER  Required OAuth provider ID, for example google

Options:
  --authorize         Verify Google's actual authorization request (no login)
  --timeout-ms MS      Request timeout from 1000 to 60000 (default: 12000)
  --help               Show this help

Environment alternatives:
  BASE_URL, OAUTH_PROVIDER_ID, TIMEOUT_MS`)
}

const parseCliArgs = (args) => {
  const options = {
    baseUrl: process.env.BASE_URL || '',
    providerId: process.env.OAUTH_PROVIDER_ID || '',
    timeoutMs: process.env.TIMEOUT_MS || 12000,
  }

  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index]
    if (arg === '--authorize') {
      options.authorize = true
      continue
    }
    if (arg === '--help') {
      return { help: true, options }
    }

    const value = args[index + 1]
    if (!value || value.startsWith('--')) {
      throw new Error(`Missing value for ${arg}.`)
    }

    if (arg === '--base-url') options.baseUrl = value
    else if (arg === '--provider') options.providerId = value
    else if (arg === '--timeout-ms') options.timeoutMs = value
    else throw new Error(`Unknown option: ${arg}`)
    index += 1
  }

  return { help: false, options }
}

const run = async () => {
  try {
    const { help, options } = parseCliArgs(process.argv.slice(2))
    if (help) {
      printHelp()
      return
    }

    const result = await fetchAndVerifyAuthProvider(options)
    if (options.authorize) {
      if (options.providerId !== 'google') throw new Error('--authorize currently supports Google only.')
      await fetchAndVerifyGoogleAuthorization(options)
      console.log('Google authorization request verified (callback, state, S256 PKCE).')
    }
    console.log(`Auth provider verified: ${result.providerId} (${result.name})`)
    console.log(`Provider discovery endpoint: ${result.url}`)
    console.log(`Canonical sign-in URL: ${result.signinUrl}`)
    console.log(`Canonical callback URL: ${result.callbackUrl}`)
  } catch (error) {
    console.error(
      `Auth provider guard failed: ${error instanceof Error ? error.message : error}`
    )
    process.exitCode = 1
  }
}

const isMain =
  process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href
if (isMain) {
  await run()
}
